105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
109	        owner.setTelephone(telephone);
110	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
115	            .anyMatch(existing -> telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone())));
116	        if (telephoneInUse) {
117	            throw new DuplicateTelephoneException(
118	                "telephone " + telephone + " is already used by another owner");
119	        }
120	        this.clinicService.saveOwner(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        headers.setLocation(UriComponentsBuilder.newInstance()
123	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
124	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
